<?php

declare(strict_types=1);

namespace Bannerstop\MentionApi\Generator;

/**
 * Turns the OpenAPI document of a Consumer into typed wrapper classes. The output depends on nothing but the
 * document, the namespace and the target: same input, same files, so a plain diff finds drift.
 */
final class WrapperGenerator
{
    /**
     * The first line of every generated file after the opening tag; a file without it is never touched.
     */
    public const MARKER = 'This file is generated by bannerstop/mention-api-client. Do not edit it; run "vendor/bin/mention-api-client generate" instead.';

    private const PARAMETER_TYPES = [
        'int' => ['int', 'int'],
        'string' => ['string', 'string'],
        'bool' => ['bool', 'bool'],
        'date' => ['string', 'string'],
        'int_list' => ['array', 'list<int>'],
        'string_list' => ['array', 'list<string>'],
    ];

    /**
     * The database types of Mention by what they arrive as: [declared type, cast]. Numbers with decimals arrive as
     * strings so that money keeps its precision; every column may be null.
     */
    private const COLUMN_TYPES = [
        'int' => ['int', 'int'], 'bigint' => ['int', 'int'], 'smallint' => ['int', 'int'], 'tinyint' => ['int', 'int'],
        'bit' => ['bool', 'bool'],
        'float' => ['float', 'float'], 'real' => ['float', 'float'],
        'decimal' => ['string', 'string'], 'numeric' => ['string', 'string'], 'money' => ['string', 'string'], 'smallmoney' => ['string', 'string'],
        'char' => ['string', 'string'], 'varchar' => ['string', 'string'], 'text' => ['string', 'string'],
        'nchar' => ['string', 'string'], 'nvarchar' => ['string', 'string'], 'ntext' => ['string', 'string'],
        'xml' => ['string', 'string'], 'uniqueidentifier' => ['string', 'string'],
        'date' => ['string', 'string'], 'time' => ['string', 'string'], 'datetime' => ['string', 'string'],
        'datetime2' => ['string', 'string'], 'smalldatetime' => ['string', 'string'], 'datetimeoffset' => ['string', 'string'],
    ];

    /**
     * @param array<string, mixed> $document  the decoded /v2/openapi.json
     * @param string               $namespace where the classes live, e.g. App\Mention
     *
     * @return array<string, string> the code of each file by its path relative to the output directory, sorted by path
     *
     * @throws GeneratorException
     */
    public function generate(array $document, string $namespace, PhpTarget $target): array
    {
        $namespace = trim($namespace, '\\');
        if (1 !== preg_match('/^[A-Za-z_][A-Za-z0-9_]*(\\\\[A-Za-z_][A-Za-z0-9_]*)*$/', $namespace)) {
            throw new GeneratorException(sprintf('"%s" is not a PHP namespace.', $namespace));
        }
        $catalog = Catalog::fromDocument($document);

        $files = [];
        foreach ($catalog->getQueries() as $query) {
            $name = ucfirst($query->getName());
            $files['Query/' . $name . 'Parameters.php'] = $this->parametersClass($namespace . '\\Query', $name . 'Parameters', 'Query', $query, $target);
            $files['Query/' . $name . 'Row.php'] = $this->rowClass($namespace . '\\Query', $name . 'Row', $query, $target);
        }
        foreach ($catalog->getRoutines() as $routine) {
            $files['Routine/' . ucfirst($routine->getName()) . 'Parameters.php'] = $this->parametersClass($namespace . '\\Routine', ucfirst($routine->getName()) . 'Parameters', 'Routine', $routine, $target);
        }
        $files['Queries.php'] = $this->queriesClass($namespace, $catalog->getQueries(), $target);
        $files['Routines.php'] = $this->routinesClass($namespace, $catalog->getRoutines(), $target);
        ksort($files, SORT_STRING);

        return $files;
    }

    /**
     * @param list<Operation> $queries
     */
    private function queriesClass(string $namespace, array $queries, PhpTarget $target): string
    {
        $imports = ['Bannerstop\\MentionApi\\MentionApiClient', 'Bannerstop\\MentionApi\\Result\\TypedRows'];
        $methods = [];
        foreach ($queries as $query) {
            $name = ucfirst($query->getName());
            $imports[] = $namespace . '\\Query\\' . $name . 'Parameters';
            $imports[] = $namespace . '\\Query\\' . $name . 'Row';
            $summary = $this->text($query->getSummary());
            $method = "    /**\n" . ('' === $summary ? '' : '     * ' . $summary . "\n     *\n")
                . '     * @return TypedRows<' . $name . "Row>\n     *\n     * @throws MentionApiException\n     */\n"
                . '    public function ' . $query->getName() . '(' . $this->parametersArgument($query, $name) . ', ?string $database = null): TypedRows' . "\n    {\n"
                . "        \$result = \$this->client->run('" . $query->getName() . "', " . $this->parametersValue($query, $name) . ", \$database);\n\n"
                . '        return new TypedRows($result, array_map([' . $name . "Row::class, 'fromArray'], \$result->getRows()));\n    }\n";
            $methods[] = $method;
        }
        if ([] !== $queries) {
            $imports[] = 'Bannerstop\\MentionApi\\Exception\\MentionApiException';
        }

        return $this->clientClass($namespace, 'Queries', 'The Queries your Consumer may call, as typed methods.', $imports, $methods, $target);
    }

    /**
     * @param list<Operation> $routines
     */
    private function routinesClass(string $namespace, array $routines, PhpTarget $target): string
    {
        $imports = ['Bannerstop\\MentionApi\\MentionApiClient'];
        $methods = [];
        foreach ($routines as $routine) {
            $name = ucfirst($routine->getName());
            $imports[] = $namespace . '\\Routine\\' . $name . 'Parameters';
            $summary = $this->text($routine->getSummary());
            $methods[] = "    /**\n" . ('' === $summary ? '' : '     * ' . $summary . "\n     *\n")
                . "     * A Routine writes to Mention and is never retried: after a TransportException or a 5xx problem it may or may not have\n     * run, so check before you run it again.\n     *\n     * @throws MentionApiException\n     */\n"
                . '    public function ' . $routine->getName() . '(' . $this->parametersArgument($routine, $name) . ', ?string $database = null): RoutineResult' . "\n    {\n"
                . "        return \$this->client->runRoutine('" . $routine->getName() . "', " . $this->parametersValue($routine, $name) . ", \$database);\n    }\n";
        }
        if ([] !== $routines) {
            $imports[] = 'Bannerstop\\MentionApi\\Exception\\MentionApiException';
            $imports[] = 'Bannerstop\\MentionApi\\Result\\RoutineResult';
        }

        return $this->clientClass($namespace, 'Routines', 'The Routines your Consumer may call, as typed methods.', $imports, $methods, $target);
    }

    /**
     * @param list<string> $imports the classes to import
     * @param list<string> $methods the code of each method
     */
    private function clientClass(string $namespace, string $class, string $summary, array $imports, array $methods, PhpTarget $target): string
    {
        sort($imports, SORT_STRING);
        $code = $this->header($namespace);
        foreach ($imports as $import) {
            $code .= 'use ' . $import . ";\n";
        }
        $code .= "\n/**\n * " . $summary . "\n */\n";
        if ($target->usesReadonlyClasses()) {
            $code .= 'final readonly class ' . $class . "\n{\n    public function __construct(private MentionApiClient \$client)\n    {\n    }\n";
        } else {
            $code .= 'final class ' . $class . "\n{\n    /** @var MentionApiClient */\n    private \$client;\n\n    public function __construct(MentionApiClient \$client)\n    {\n        \$this->client = \$client;\n    }\n";
        }
        foreach ($methods as $method) {
            $code .= "\n" . $method;
        }

        return $code . "}\n";
    }

    /**
     * Nothing is needed to call an operation without required Parameters, so its Parameters may be left out.
     */
    private function parametersArgument(Operation $operation, string $name): string
    {
        return $this->needsParameters($operation) ? $name . 'Parameters $parameters' : '?' . $name . 'Parameters $parameters = null';
    }

    private function parametersValue(Operation $operation, string $name): string
    {
        return $this->needsParameters($operation) ? '$parameters->toArray()' : '($parameters ?? new ' . $name . 'Parameters())->toArray()';
    }

    private function needsParameters(Operation $operation): bool
    {
        foreach ($operation->getParameters() as $parameter) {
            if ($parameter->isRequired()) {
                return true;
            }
        }

        return false;
    }

    private function parametersClass(string $namespace, string $class, string $kind, Operation $operation, PhpTarget $target): string
    {
        $fields = [];
        foreach ($operation->getParameters() as $parameter) {
            $type = self::PARAMETER_TYPES[$parameter->getType()];
            $optional = !$parameter->isRequired();
            $fields[] = new Field($parameter->getName(), ($optional ? '?' : '') . $type[0], $type[1] . ($optional ? '|null' : ''), '', $optional);
        }

        $required = [];
        $optional = [];
        foreach ($fields as $field) {
            if ($field->isOptional()) {
                $optional[] = $field;
            } else {
                $required[] = $field;
            }
        }
        $entries = '';
        foreach ($required as $field) {
            $entries .= "            '" . $field->getName() . "' => \$this->" . $field->getName() . ",\n";
        }
        $array = [] === $required ? '[]' : "[\n" . $entries . '        ]';
        $method = "    /**\n     * @return array<string, mixed> the Parameters by name, as the body of the call needs them\n     */\n    public function toArray(): array\n    {\n";
        if ([] === $optional) {
            $method .= '        return ' . $array . ";\n    }\n";
        } else {
            $method .= '        $parameters = ' . $array . ";\n";
            foreach ($optional as $field) {
                $method .= '        if (null !== $this->' . $field->getName() . ") {\n            \$parameters['" . $field->getName() . "'] = \$this->" . $field->getName() . ";\n        }\n";
            }
            $method .= "\n        return \$parameters;\n    }\n";
        }

        return $this->classCode($namespace, $class, 'The Parameters of the ' . $kind . ' "' . $operation->getName() . '".', $fields, $target, $method);
    }

    private function rowClass(string $namespace, string $class, Operation $operation, PhpTarget $target): string
    {
        $fields = [];
        $arguments = '';
        foreach ($operation->getColumns() as $column) {
            $type = self::COLUMN_TYPES[$column->getType()] ?? null;
            $fields[] = new Field($column->getName(), null === $type ? '' : '?' . $type[0], null === $type ? 'mixed' : $type[0] . '|null', $column->getDescription());
            $access = "\$row['" . $column->getName() . "']";
            $arguments .= '            ' . (null === $type ? $access . ' ?? null' : 'isset(' . $access . ') ? (' . $type[1] . ') ' . $access . ' : null') . ",\n";
        }
        $method = "    /**\n     * Reads a row of the answer; a missing column is null and a column the Query does not declare is ignored.\n     *\n     * @param array<string, mixed> \$row\n     */\n    public static function fromArray(array \$row): self\n    {\n";
        $method .= [] === $fields ? "        return new self();\n" : "        return new self(\n" . $arguments . "        );\n";
        $method .= "    }\n";

        return $this->classCode($namespace, $class, 'A row of the Query "' . $operation->getName() . '".', $fields, $target, $method);
    }

    /**
     * @param list<Field> $fields
     * @param string      $methods the code of the methods after the constructor
     */
    private function classCode(string $namespace, string $class, string $summary, array $fields, PhpTarget $target, string $methods): string
    {
        $readonly = $target->usesReadonlyClasses();
        $code = $this->header($namespace) . "/**\n * " . $this->text($summary) . "\n */\n";
        $code .= ($readonly ? 'final readonly class ' : 'final class ') . $class . "\n{\n";

        $params = [];
        foreach ($fields as $field) {
            if ($field->needsDocType() || '' !== $field->getDescription()) {
                $params[] = '     * @param ' . $field->getDocType() . ' $' . $field->getName() . ('' === $field->getDescription() ? '' : ' ' . $this->text($field->getDescription()));
            }
        }
        $constructorDoc = [] === $params ? '' : "    /**\n" . implode("\n", $params) . "\n     */\n";

        if ($readonly) {
            $code .= $constructorDoc;
            if ([] === $fields) {
                $code .= "    public function __construct()\n    {\n    }\n";
            } else {
                $code .= "    public function __construct(\n";
                foreach ($fields as $field) {
                    $code .= '        public ' . $this->signature($field, true) . ",\n";
                }
                $code .= "    ) {\n    }\n";
            }
        } else {
            foreach ($fields as $field) {
                $code .= $this->propertyDocblock($field);
                $code .= '    public ' . ('' === $field->getDeclaredType() ? '' : $field->getDeclaredType() . ' ') . '$' . $field->getName() . ";\n\n";
            }
            $code .= $constructorDoc;
            $code .= '    public function __construct(' . implode(', ', array_map(function (Field $field): string {
                return $this->signature($field, false);
            }, $fields)) . ")\n    {\n";
            foreach ($fields as $field) {
                $code .= '        $this->' . $field->getName() . ' = $' . $field->getName() . ";\n";
            }
            $code .= "    }\n";
        }

        return $code . "\n" . $methods . "}\n";
    }

    private function signature(Field $field, bool $readonly): string
    {
        $type = $field->getDeclaredType();
        if ('' === $type && $readonly) {
            $type = 'mixed';
        }

        return ('' === $type ? '' : $type . ' ') . '$' . $field->getName() . ($field->isOptional() ? ' = null' : '');
    }

    private function propertyDocblock(Field $field): string
    {
        $lines = [];
        if ('' !== $field->getDescription()) {
            $lines[] = $this->text($field->getDescription());
            $lines[] = '';
        }
        if ($field->needsDocType()) {
            $lines[] = '@var ' . $field->getDocType();
        }
        $lines[] = '@readonly';
        if (['@readonly'] === $lines) {
            return "    /** @readonly */\n";
        }

        return "    /**\n" . implode('', array_map(static function (string $line): string {
            return '' === $line ? "     *\n" : '     * ' . $line . "\n";
        }, $lines)) . "     */\n";
    }

    /**
     * Text from the document for a comment: one line, and no way to end the comment early.
     */
    private function text(string $text): string
    {
        return str_replace('*/', '* /', trim((string) preg_replace('/\s+/', ' ', $text)));
    }

    private function header(string $namespace): string
    {
        return "<?php\n\ndeclare(strict_types=1);\n\n// " . self::MARKER . "\n\nnamespace $namespace;\n\n";
    }
}
